style.css:
@-moz-document domain("sploop.io") {
body {
    background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
    background-size: 400% 400%;
    animation: neonFlow 15s ease infinite;
    font-family: 'Orbitron', sans-serif;
    color: #fff;
    margin: 0;
  }

  @keyframes neonFlow {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  }

  /* Logo custom */
  #mainLogo {
    content: url('https://i.imgur.com/ybnsAVD.jpeg'); /* Replace with your custom Sploop.io logo if desired */
    max-width: 300px;
    display: block;
    margin: 40px auto 20px auto;
    filter: drop-shadow(0 0 10px #0ff) contrast(120%);
  }

  /* Button hover glow */
  button:hover, .button:hover {
    background-color: #0ff !important;
    color: #000 !important;
    box-shadow: 0 0 10px #0ff, 0 0 20px #0ff;
    transition: all 0.3s ease;
  }

  /* Neon outline for UI panels */
  .ui-panel {
    border: 2px solid #0ff !important;
    box-shadow: 0 0 15px #0ff;
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Input fields */
  input, select, textarea {
    background: rgba(0, 0, 0, 0.5) !important;
    border: 1px solid #0ff !important;
    color: #0ff !important;
    font-family: 'Orbitron', sans-serif;
  }

  /* Title animation */
  h1, h2, h3 {
    text-shadow: 0 0 10px #0ff, 0 0 20px #00f;
    animation: pulse 3s infinite;
  }

  @keyframes pulse {
    0% { text-shadow: 0 0 10px #0ff, 0 0 20px #00f; }
    50% { text-shadow: 0 0 20px #0ff, 0 0 40px #00f; }
    100% { text-shadow: 0 0 10px #0ff, 0 0 20px #00f; }
  }
}
